const $ = (s, root = document) => root.querySelector(s);
const app = $('#app');
const API_BASE = '/api/kitchen/rooms';
const shareUrl = (role, roomPin=pin) => `${location.origin}/?battle=7&${role}=${encodeURIComponent(roomPin)}`;
let retryDelay = 3000;
function syncParentRoute(){if(window.parent!==window)window.parent.postMessage({type:'crazy-kitchen:navigate',search:location.search},location.origin);}
const INGREDIENTS = {Bread:'🍞',Egg:'🥚',Cheese:'🧀',Tomato:'🍅',Chicken:'🍗',Mushroom:'🍄',Milk:'🥛',Chocolate:'🍫',Fruit:'🍓',Rice:'🍚'};
const TEAM_ICONS = ['🍅','🥑','🍋','🍇','🥕','🫐','🌽','🍒','🥦','🍊'];
const FORMAT = {typed_correction:'Fix the sentence',multiple_choice:'Pick the best answer',sentence_rebuild:'Build the sentence'};
const STATUS = {waiting:'Waiting',submitted:'Submitted',accepted:'Accepted',rejected:'Rejected'};
let mode = 'home', pin = '', token = '', state = null, pending = null, lastAttempt = 0, clockOffset = 0;
let routeGeneration=0, pollInFlight=null, actionInFlight=null, joinInFlight=null, pendingJoin=null, joinLastAttempt=0, joinRetryDelay=3000;
const ui = {error:'',notice:'',online:navigator.onLine,loading:false,busy:false,review:false,tab:'play',selected:[],wordOrder:[],answer:'',questionId:null,modal:null,slot:0,teamName:'',form:{teamCount:'10',rushSeconds:'30',roomName:'Crazy Kitchen'},signature:''};
const memory = new Map();
const storage = {get(key){try{return localStorage.getItem(key) ?? memory.get(key);}catch{return memory.get(key);}},set(key,value){memory.set(key,value);try{localStorage.setItem(key,value);}catch{}},remove(key){memory.delete(key);try{localStorage.removeItem(key);}catch{}}};
const credentialKey = () => `crazy-kitchen:${mode === 'host' ? 'host' : 'team'}:${pin}`;
const pendingKey = () => `crazy-kitchen:pending:${mode}:${pin}`;
const pendingJoinKey = (roomPin=pin) => `crazy-kitchen:pending-join:${roomPin}`;
function readPendingJoin(roomPin){try{const value=JSON.parse(storage.get(pendingJoinKey(roomPin)) || 'null');return value&&value.pin===roomPin&&/^\d{5}$/.test(value.pin)&&/^[-a-zA-Z0-9]{20,100}$/.test(value.clientId)&&Number.isInteger(value.teamSlot)&&value.teamSlot>=1&&value.teamSlot<=10&&typeof value.name==='string'&&value.name.trim().length>0&&value.name.length<=28?value:null;}catch{return null;}}
const esc = (s) => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;
const icon = (slot) => TEAM_ICONS[((slot || 1)-1)%TEAM_ICONS.length];
const disabled = (condition) => condition ? ' disabled' : '';
const totalStock = (inventory = {}) => Object.values(inventory).reduce((a,b)=>a+Number(b || 0),0);
const phaseLabel = () => ({lobby:'Prep time',question:'On the menu',reveal:'The answer is in',rush:state?.rushEnded?'Service complete':state?.questionNumber===20?'Last orders!':'Cooking time',finished:'Service complete',closed:'Kitchen closed'}[state?.phase] || 'Ready, chef?');
const remaining = () => Math.max(0,Math.ceil(((state?.rushEndsAt || 0) - Date.now() - clockOffset)/1000));
const rushActive = () => state?.phase === 'rush' && !state.rushEnded && remaining() > 0;
const brand = (compact=false) => `<a class="brand ${compact?'compact':''}" href="./index.html" aria-label="Crazy Kitchen home"><span class="brand-mark" aria-hidden="true">🍳</span><span>crazy<span class="brand-second">kitchen<span class="brand-dot">.</span></span></span></a>`;
const connection = () => `<span class="connection ${ui.online?'':'is-offline'}"><i></i><span>${ui.online?'Live kitchen':'Reconnecting…'}</span></span>`;
const btn = (label,action,cls='button',extra='') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function announce(text){$('#announcer').textContent=text;}
function setNotice(text){ui.notice=text;announce(text);setTimeout(()=>{if(ui.notice===text){ui.notice='';render();}},5000);}
function render(){
  const reviewScroll=$('.review-list')?.scrollTop || 0, modalScroll=$('.modal-card')?.scrollTop || 0;const active=document.activeElement,focusData=active?.dataset?.action?{...active.dataset}:null,focusId=active?.id,selection=active && ['TEXTAREA','INPUT'].includes(active.tagName)?[active.selectionStart,active.selectionEnd]:null;
  document.body.dataset.role=mode;
  app.innerHTML = `${mode==='home'?home():mode==='join'&&pendingJoin?joinRecoveryView():!state?loadingView():state.phase==='closed'?closedView():mode==='host'?!token?missingHost():host():mode==='screen'?projector():state.me?pupil():joinView()}${feedback()}${modal()}`;
  if(focusId){const next=document.getElementById(focusId);if(next){next.focus({preventScroll:true});try{if(selection)next.setSelectionRange(...selection);}catch{}}}
  if($('.review-list'))$('.review-list').scrollTop=reviewScroll;if($('.modal-card'))$('.modal-card').scrollTop=modalScroll;if(!focusId&&focusData){const next=[...document.querySelectorAll('[data-action]')].find(el=>Object.entries(focusData).every(([key,value])=>el.dataset[key]===value));if(next&&!next.disabled)next.focus({preventScroll:true});}
  updateTimers();
}
function feedback(){return `${ui.error?`<div class="toast error" role="alert"><span>${esc(ui.error)}</span>${btn('×','clear-error','icon-button','aria-label="Dismiss error"')}</div>`:''}${ui.notice?`<div class="toast" role="status"><span>${esc(ui.notice)}</span>${btn('×','clear-notice','icon-button','aria-label="Dismiss message"')}</div>`:''}${pending?`<div class="pending-strip" role="status"><span class="spinner"></span><span>${ui.online?'Confirming your action…':'Action not confirmed. Reconnecting and retrying safely…'}</span>${btn('Retry now','retry','text-button')}</div>`:''}`;}
function home(){return `<div class="site-shell"><header class="site-header">${brand()}<nav class="landing-nav"><a class="text-link" href="#how-it-works">How to play</a><a class="text-link all-battles" href="/" target="_top">All battles ↗</a></nav></header><main id="main"><section class="landing-hero"><div class="hero-copy"><span class="eyebrow"><i class="live-dot"></i> THE CLASSROOM IS COOKING</span><h1>A little grammar.<br>A lot of <em>flavour.</em></h1><p>Good answers. Mystery ingredients.<br>One deliciously competitive classroom.</p><div class="hero-actions"><a class="button coral" href="#start-kitchen">Open your kitchen <span>↗</span></a><a class="text-link" href="#join-kitchen">I’m on a team →</a></div><div class="hero-meta"><span>2–10 teams</span><i></i><span>20 questions</span><i></i><span>20 rounds</span></div></div><div class="hero-art"><img src="./assets/kitchen-hero.png" alt="A cheerful little chef tossing vegetables in a busy, colourful kitchen" fetchpriority="high"><div class="hero-art-shade"></div><span class="art-sticker"><b>YES, CHEF!</b><small>Bring your best ideas.</small></span><div class="floating-recipe"><span>🍅 + 🧀 + 🍞</span><b>What will you cook?</b><small>Every round is a new adventure.</small></div></div></section><section class="start-grid"><form id="create-form" class="create-card"><div class="card-heading"><span class="step-label">01 / FOR TEACHERS</span><span aria-hidden="true">✳</span></div><h2 id="start-kitchen">Your kitchen.<br>Your classroom.</h2><p>Set up a room. Share the PIN. Let them cook.</p><div class="field"><label for="room-name">Kitchen name</label><input id="room-name" name="roomName" maxlength="48" value="${esc(ui.form.roomName)}" required></div><div class="field-pair"><div class="field"><label for="team-count">Number of teams</label><select id="team-count" name="teamCount">${Array.from({length:9},(_,i)=>i+2).map(n=>`<option value="${n}" ${String(n)===ui.form.teamCount?'selected':''}>${n} teams</option>`).join('')}</select></div><div class="field"><label for="rush-length">Cooking time</label><select id="rush-length" name="rushSeconds">${[30,45,60,90].map(n=>`<option value="${n}" ${String(n)===ui.form.rushSeconds?'selected':''}>${n} seconds</option>`).join('')}</select></div></div><button class="button cream wide" type="submit"${disabled(ui.loading)}>${ui.loading?'Opening your kitchen…':'Create a kitchen'} <span>↗</span></button><small class="card-footnote">One teacher screen. One phone per team. No accounts.</small></form><form id="pin-form" class="join-card"><div class="card-heading"><span class="step-label">02 / FOR TEAMS</span><span aria-hidden="true">✴</span></div><div><h2 id="join-kitchen">Aprons on.<br>Brains ready.</h2><p>Your teacher has the room PIN.<br>Type it here to grab your place.</p></div><div class="field"><label for="join-pin">Room PIN</label><input id="join-pin" class="pin-input" name="pin" placeholder="00000" inputmode="numeric" autocomplete="off" pattern="[0-9]{5}" maxlength="5" required aria-describedby="pin-help"><small id="pin-help">Use one phone or tablet for your whole team.</small></div><button class="button green wide" type="submit">Join the kitchen <span>→</span></button><div class="join-decor" aria-hidden="true">🍞 <span>+</span> 🥚 <span>+</span> 🧀 <span>=</span> <b>?</b></div></form></section><section id="how-it-works" class="how-section"><div class="section-heading"><span class="eyebrow">THE RECIPE FOR A GREAT LESSON</span><h2>Think. Collect. <em>Cook.</em></h2></div><div class="how-grid"><article><span class="how-number">01</span><h3>Answer together</h3><p>Fix sentences, pick an answer, or put words in order. Your teacher reviews every team’s answer.</p></article><article><span class="how-number">02</span><h3>Stock your pantry</h3><p>Every accepted answer earns one random ingredient. Save your ingredients and plan your next dish.</p></article><article><span class="how-number">03</span><h3>Make something magic</h3><p>After each question, cook or save your ingredients. Combine exactly three ingredients, discover secret recipes, and earn stars.</p></article></div><div class="rule-strip"><span>⭐ Stars, then accepted answers</span><span>✨ First discovery earns +1</span><span>🔥 A burnt dish earns 0</span><span>🕵️ One secret recipe unlocks a surprise</span></div></section></main><footer class="site-footer"><b>A little teamwork goes a long way.</b><span>Made for curious minds & hungry imaginations.</span></footer></div>`;}
function loadingView(){return `<div class="site-shell"><header class="site-header">${brand()}${connection()}</header><main id="main" class="center-state"><span class="loading-pan" aria-hidden="true">🍳</span><h1>${ui.error?'Let’s get you connected.':'Finding your kitchen…'}</h1><p>${ui.error?'Check the room PIN and your connection, then try again.':'Your place is saved on this device.'}</p>${ui.error?`${btn('Try again','reload','button green')} <a class="button secondary" href="./index.html">Back home</a>`:''}</main></div>`;}
function missingHost(){return `<main id="main" class="center-state">${brand()}<span class="big-symbol">🔒</span><h1>This is the teacher’s desk.</h1><p>Open this room on the browser where you created it. The private teacher key stays on that device.</p><a class="button green" href="${esc(shareUrl('screen'))}">Open public projector</a><a class="text-link" href="./index.html">Back home</a></main>`;}
function closedView(){return `<main id="main" class="center-state">${brand()}<span class="big-symbol">👋</span><h1>The kitchen is closed.</h1><p>Thanks for cooking with us. Ask your teacher for a new room PIN to play again.</p><a class="button green" href="./index.html">Back to the kitchen</a></main>`;}
function appHeader(role){return `<header class="game-header"><div class="header-brand">${brand(true)}<a class="all-battles text-link" href="/" target="_top">All battles ↗</a><span class="role-tag">${role==='host'?'Teacher’s desk':role==='screen'?'Classroom screen':esc(state.me?.name || 'Join your team')}</span></div><div class="header-right">${connection()}${role!=='team'?`<span class="room-chip">ROOM <b>${esc(pin)}</b></span>`:`<span class="star-total"><span>★</span> ${state.me?.stars || 0}</span>`}${role==='host'?btn('End room','end-confirm','text-button subtle'):role==='screen'?btn('⛶','fullscreen','icon-button','aria-label="Toggle fullscreen"'):''}</div></header>`;}
function progress(){const q=state.questionNumber || 0;return `<div class="round-progress" aria-label="Question ${q} of ${state.totalQuestions || 20}"><span>${state.phase==='lobby'?'The kitchen is warming up':`Question ${q} of ${state.totalQuestions || 20}`}</span><div class="round-dots">${Array.from({length:20},(_,i)=>`<i class="${i<q?'done':''} ${i===q-1?'current':''} " title="Question ${i+1}"></i>`).join('')}</div><span>${state.phase==='rush'?'Cook or save':'One question · one round'}</span></div>`;}
function host(){return `${appHeader('host')}<main id="main" class="host-layout"><div class="host-main"><section class="desk-heading"><div><span class="eyebrow">WELCOME TO YOUR</span><h1>${esc(state.roomName)}</h1></div><a class="button secondary small" href="${esc(shareUrl('screen'))}" target="_blank" rel="noopener">Open projector <span>↗</span></a></section><div class="privacy-note"><span>🔒</span> Your review panel contains private answers. Share the separate projector window with the class.</div>${progress()}${kitchenScene('host')}${state.phase==='lobby'?joinDetails():state.phase==='finished'?finalStage('host'):''}<section class="leaderboard-section"><div class="section-title"><div><span class="eyebrow">THE COMPETITION</span><h2>Kitchen leaderboard</h2></div><span class="muted">${state.teams.filter(t=>t.online).length} teams online</span></div>${leaderboard()}</section>${activity()}</div>${reviewPanel()}</main>`;}
function prompt(question){return (question?.promptSegments || [{text:question?.prompt || '',bold:false}]).map(s=>s.bold?`<strong>${esc(s.text)}</strong>`:esc(s.text)).join('');}
function questionStage(){const q=state.question; if(!q)return `<section class="stage question-stage"><h2>Preparing your next question…</h2></section>`;return `<section class="stage question-stage ${state.phase==='reveal'?'is-revealed':''}"><div class="question-topline"><span class="pill">${esc(FORMAT[q.format] || 'English challenge')}</span><span class="question-index">${String(state.questionNumber).padStart(2,'0')} <span>/ 20</span></span></div><p class="question-instruction">${esc(q.instruction)}</p><h2 class="question-prompt">${prompt(q)}</h2>${q.format==='multiple_choice'?`<div class="display-options">${(q.options || []).map((o,i)=>`<div><span>${String.fromCharCode(65+i)}</span>${esc(o.text)}</div>`).join('')}</div>`:''}${q.format==='sentence_rebuild'?`<div class="display-tokens">${(q.tokens || []).map(t=>`<span>${esc(typeof t==='string'?t:t.text)}</span>`).join('')}</div>`:''}${state.phase==='reveal'&&state.answerReveal?`<div class="answer-reveal"><span class="eyebrow">✓ THE ANSWER IS IN</span><h3>${esc(state.answerReveal.canonicalAnswer)}</h3><p>${esc(state.answerReveal.feedback?.explanation || '')}</p></div>`:`<div class="question-foot"><span><i class="live-dot"></i> Every team answers at the same time</span><span>${state.teams.filter(t=>t.submissionStatus!=='waiting').length} / ${state.teams.length} submitted</span></div>`}</section>`;}
function recentCooks(){const cooks=[...(state.latestCooks || [])].reverse().slice(0,5);return `<div class="recent-cooks"><div class="recent-label"><i class="live-dot"></i> FRESH FROM THE KITCHEN</div>${cooks.length?`<div class="cook-feed">${cooks.map(c=>`<article class="cook-item ${c.dish?.success===false?'burnt':''}"><span class="dish-icon">${esc(c.dish?.emoji || '🍽️')}</span><div><b>${esc(c.dish?.name || 'Mystery dish')}</b><small>${esc(c.teamName)}</small></div><span class="cook-stars">${Number(c.starsEarned)>0?`+${c.starsEarned} ★`:['power','steal'].includes(c.dish?.type)?'🕵️':'0 ★'}</span>${c.discoveryBonus?'<span class="discovery-dot" title="First discovery bonus">✦</span>':''}</article>`).join('')}</div>`:`<div class="empty-feed">The pass is clear. Who will plate up first?</div>`}</div>`;}
function leaderboard(){return `<div class="leaderboard">${[...state.teams].sort((a,b)=>b.stars-a.stars||(b.acceptedCount||0)-(a.acceptedCount||0)||a.slot-b.slot).map((t,i)=>`<article class="team-card team-color-${(t.slot-1)%5}"><div class="team-card-top"><span class="team-avatar">${icon(t.slot)}</span><span class="place">${i===0&&t.stars>0?'♛':String(i+1).padStart(2,'0')}</span></div><h3>${esc(t.name)}</h3><div class="team-card-bottom"><strong>${t.stars}<span> ★</span></strong><span>${t.inventoryCount} ingredients<br>${t.acceptedCount || 0} accepted</span></div></article>`).join('')}</div>`;}
function reviewPanel(){const submissions=(state.submissions || []).filter(s=>s.status!=='waiting'), unreviewed=submissions.filter(s=>s.status==='submitted').length, joined=state.takenSlots?.length ?? state.teams.length;return `<aside class="review-panel" aria-label="Teacher controls and answer review"><div class="panel-top"><span class="eyebrow">TEACHER’S DESK</span><span class="lock-icon">🔒</span><h2>${phaseLabel()}</h2></div><div class="control-block">${hostControl(unreviewed,joined)}</div>${['question','reveal'].includes(state.phase)?`<div class="sidebar-challenge">${questionStage('host')}</div>`:''}${state.phase==='rush'?`<div class="sidebar-cooking"><span class="eyebrow">COOK OR SAVE</span><div class="sidebar-clock"><strong data-timer>${remaining()}</strong><span>seconds maximum</span></div><p>Teams may cook with exactly three ingredients, or save them. You can finish cooking whenever everyone is ready.</p></div>`:''}<div class="response-heading"><h3>Team response status</h3><span>${submissions.length}/${state.teams.length}</span></div><div class="status-list">${state.teams.length?state.teams.map(t=>`<div class="status-row"><div class="status-team"><span class="mini-avatar">${icon(t.slot)}</span><div><b>${esc(t.name)}</b><small><i class="online-dot ${t.online?'online':''}"></i> ${t.online?'Connected':'Reconnecting'}</small></div></div><span class="status-badge ${esc(t.submissionStatus)}">${esc(STATUS[t.submissionStatus] || 'Waiting')}</span></div>`).join(''):'<p class="empty-roster">Your teams will appear here when they join.</p>'}</div>${['question','reveal'].includes(state.phase)?`<div class="review-toggle">${btn(`Review answers <span>${submissions.length}</span>`, 'toggle-review','button green wide',disabled(!submissions.length))}<p class="tiny muted">Answers stay private until you open review.</p></div>`:''}<div class="desk-tip"><span>✦</span><p>${state.phase==='lobby'?'Start when your teams have joined. They begin with empty pantries and zero stars.':state.phase==='question'?'An accepted answer earns exactly one ingredient. You can change a decision until you reveal.':state.phase==='rush'?'Cooking is optional. A failed dish never removes existing stars.':'You decide when the next round begins.'}</p></div></aside>`;}
function answerReviewModal(){const submissions=(state.submissions || []).filter(s=>s.status!=='waiting');return `<div class="modal-backdrop review-backdrop"><section class="modal-card review-dialog" role="dialog" aria-modal="true" aria-labelledby="review-title"><header class="review-modal-heading"><div><span class="eyebrow">TEACHER ONLY</span><h2 id="review-title">Review team answers</h2><p>${submissions.length} of ${state.teams.length} teams submitted</p></div>${btn('×','toggle-review','icon-button','aria-label="Close answer review"')}</header><div class="answer-key"><span class="eyebrow">PRIVATE ANSWER KEY</span><h4>${esc(state.answerKey?.canonicalAnswer || 'Key unavailable')}</h4>${state.answerKey?.acceptedVariants?.length?`<p><b>Also accept:</b> ${esc(state.answerKey.acceptedVariants.join(' / '))}</p>`:''}<p>${esc(state.answerKey?.feedback?.explanation || '')}</p></div><div class="review-list">${state.teams.map(t=>{const answer=(state.submissions || []).find(x=>x.teamId===t.id),s=answer?.status!=='waiting'?answer:null;return `<article class="review-team"><div class="review-team-head"><b>${icon(t.slot)} ${esc(t.name)}</b><span class="status-badge ${esc(s?.status || 'waiting')}">${esc(STATUS[s?.status] || 'Waiting')}</span></div><div class="submitted-answer">${s?esc(s.answer):'<em>No answer yet.</em>'}${s?.reward?`<p class="reward-line">${INGREDIENTS[s.reward] || '🥣'} +1 ${esc(s.reward)}</p>`:''}</div><div class="judge-actions">${btn('✓ Accept','accept',`judge accept ${s?.status==='accepted'?'selected':''}`,`data-team="${esc(t.id)}"${disabled(!s || ui.busy || state.phase!=='question')}`)}${btn('× Reject','reject',`judge reject ${s?.status==='rejected'?'selected':''}`,`data-team="${esc(t.id)}"${disabled(!s || ui.busy || state.phase!=='question')}`)}</div></article>`;}).join('')}</div><footer class="review-modal-footer"><p>Teacher judgment decides. Reveal and advance are separate controls.</p>${btn('Done','toggle-review','button green')}</footer></section></div>`;}
function hostControl(unreviewed,joined){switch(state.phase){case'lobby':return `<p><b>${joined} of ${state.teamCount}</b> teams have joined.</p>${btn('Start the game →','start','button coral wide',disabled(ui.busy||joined<state.teamCount))}<p class="tiny muted">All configured teams need to join before you start.</p>`;case'question':return `<p><b>${unreviewed}</b> answer${unreviewed===1?'':'s'} to review</p>${btn('Reveal answer →','reveal','button coral wide',disabled(ui.busy||unreviewed>0))}<p class="tiny muted">Review submitted answers first. Teams still waiting will miss this question.</p>`;case'reveal':return `<p>Answer revealed. Ready for what’s next?</p>${btn(state.questionNumber===20?'Open last orders 🍳':'Cook or save ingredients 🍳','advance','button coral wide',disabled(ui.busy))}`;case'rush':return `<p>${state.rushEnded?'Service has finished.':`Round ${state.questionNumber} · cooking is optional`}</p>${state.rushEnded?btn(state.questionNumber===20?'Show final results ★':'Next question →','advance','button coral wide',disabled(ui.busy)):btn('Finish cooking','end-rush','button secondary wide',disabled(ui.busy))}`;case'finished':return `<p>That was a delicious effort.</p><a class="button coral wide" href="./index.html">Set up a new kitchen ↗</a>`;default:return'';}}
function activity(){return `<section class="activity-section"><div class="section-title"><h2>Kitchen chatter</h2><span class="eyebrow">RECENT ACTIVITY</span></div><div class="activity-list">${[...(state.events || [])].reverse().slice(0,5).map(e=>`<p><span>✦</span>${esc(e.text)}</p>`).join('')||'<p><span>✦</span>A new kitchen. A fresh start. Let’s see what happens.</p>'}</div></section>`;}
function kitchenScene(role){return `<section class="kitchen-scene" aria-label="Crazy Kitchen classroom board"><img src="./assets/kitchen-hero.png" alt="The Crazy Kitchen chef tossing fresh ingredients over a lively stove"><div class="scene-label"><span class="live-dot"></span>${state.phase==='lobby'?'PREPARING FOR SERVICE':state.phase==='rush'?(rushActive()?'THE KITCHEN IS OPEN':'PANS DOWN, CHEFS'):state.phase==='finished'?'A BRILLIANT SERVICE':'GREAT IDEAS ARE COOKING'}</div>${role==='screen'&&ui.publicCook?publicCookPopup(ui.publicCook):''}</section>`;}
function joinDetails(){return `<section class="join-details"><div><span class="eyebrow">GRAB ONE PHONE PER TEAM</span><h2>Scan. Join. Get cooking.</h2><p>Or open <b>${esc(`${location.origin}/?battle=7`)}</b> and enter the PIN.</p><div class="join-pin-row"><strong>${esc(pin)}</strong>${mode==='host'?btn('Copy join link ↗','copy-join','button green small'):''}</div></div><img class="join-qr" src="${API_BASE}/${esc(pin)}/qr.svg" alt="Scan this QR code to join room ${esc(pin)}"></section>`;}
function projector(){return `${appHeader('screen')}<main id="main" class="projector-main"><div class="projector-heading"><h1>${esc(state.roomName)}</h1><span>${phaseLabel()}</span></div>${progress()}<div class="projector-board">${kitchenScene('screen')}<aside class="projector-side">${state.phase==='lobby'?joinDetails():state.phase==='finished'?finalStage('screen'):state.phase==='rush'?`<section class="projector-cooking"><span class="eyebrow">ROUND ${state.questionNumber} · COOK OR SAVE</span><h2>${rushActive()?'Yes, chef!':'Pans down!'}</h2><div class="rush-clock"><strong data-timer>${remaining()}</strong><span>SECONDS</span></div><p>${rushActive()?'Combine three ingredients on your team’s phone, or save them for another round.':'Your ingredients are saved. Your teacher will start the next round.'}</p><small>⭐ First global recipe discovery earns +1</small></section>`:questionStage('screen')}</aside></div><section class="projector-leaderboard">${leaderboard()}</section>${state.phase==='rush'?recentCooks():''}</main>`;}
function publicCookPopup(c){const d=c.dish || {};return `<div class="public-cook-popup ${d.success===false?'burnt':''}" role="status"><span class="eyebrow">${esc(c.teamName)} · ${c.discoveryBonus?'FIRST DISCOVERY!':'ORDER UP!'}</span><span class="popup-dish">${esc(d.emoji || '🍽️')}</span><h2>${esc(d.name)}</h2><strong>${c.starsEarned>0?`+${c.starsEarned} ★`:d.type==='steal'?'🕵️ Sneaky Snack power':'0 ★'}</strong><p>${d.success===false?'A brave experiment. Try a new combination!':c.discoveryBonus?'Includes the +1 discovery bonus.':'Fresh from the kitchen.'}</p></div>`;}
const seenCookIds=new Set();let cookQueue=[],cookQueueTimer=null,cookHistoryInitialized=false;
function queuePublicCooks(next){if(mode!=='screen')return;const cooks=next.latestCooks || [];if(!cookHistoryInitialized){cooks.forEach(c=>seenCookIds.add(c.id));cookHistoryInitialized=true;return;}cooks.filter(c=>!seenCookIds.has(c.id)).sort((a,b)=>a.at-b.at).forEach(c=>{seenCookIds.add(c.id);cookQueue.push(c);});showNextPublicCook();}
function showNextPublicCook(){if(ui.publicCook||!cookQueue.length)return;ui.publicCook=cookQueue.shift();render();cookQueueTimer=setTimeout(()=>{ui.publicCook=null;render();cookQueueTimer=setTimeout(()=>{cookQueueTimer=null;showNextPublicCook();},350);},3600);}
function finalStage(){const winners=state.teams.filter(t=>state.winners?.includes(t.id)),names=winners.map(t=>t.name).join(' & ');return `<section class="final-stage stage"><div class="confetti" aria-hidden="true">✦ <span>✧</span> ✦ <span>✧</span> ✦</div><span class="eyebrow">THAT’S A WRAP, CHEFS</span><span class="trophy" aria-hidden="true">🏆</span><h2>${winners.length>1?'A delicious tie.':'The stars of the kitchen.'}</h2><h3>${esc(names || 'Every chef who gave it a go')}</h3><p>${winners[0]?`${winners[0].stars} stars. `:''}Great teamwork. Bold choices. Brilliant cooking.</p><span class="final-caption">Ranked by stars, then accepted answers. Equal on both? Share the crown.</span></section>`;}
function joinView(){if(state.phase!=='lobby')return `<main id="main" class="center-state">${brand()}<span class="big-symbol">🍳</span><h1>This kitchen has already started.</h1><p>Reopen the browser your team used to join, or ask your teacher about the next game.</p><a class="button green" href="./index.html">Back to the kitchen</a></main>`;return `<div class="site-shell narrow"><header class="site-header">${brand(true)}${connection()}</header><main id="main" class="join-room"><div class="join-room-heading"><span class="eyebrow">ROOM ${esc(pin)} · ${esc(state.roomName)}</span><h1>Pick your<br><em>kitchen crew.</em></h1><p>One device per team. Your place stays saved here.</p></div><form id="team-form"><div class="team-slots">${Array.from({length:state.teamCount},(_,i)=>i+1).map(n=>{const taken=state.takenSlots?.includes(n),t=state.teams.find(t=>t.slot===n);return `<button class="team-slot team-color-${(n-1)%5} ${ui.slot===n?'selected':''}" type="button" data-action="select-team" data-slot="${n}" aria-pressed="${ui.slot===n}"${disabled(taken||ui.loading)}><span>${icon(n)}</span><b>${taken?esc(t?.name || `Team ${n}`):`Team ${n}`}</b><small>${taken?'Already taken':ui.slot===n?'Your team ✓':'Grab this spot'}</small></button>`;}).join('')}</div><div class="field"><label for="team-name">Give your team a name</label><input id="team-name" name="teamName" maxlength="24" placeholder="The Saucy Squad" value="${esc(ui.teamName)}" required autocomplete="off"></div><button class="button green wide" type="submit"${disabled(!ui.slot||ui.loading)}>${ui.loading?'Saving your place…':'Aprons on. Let’s go! →'}</button><a class="text-link back-home" href="./index.html">← Use a different PIN</a></form></main></div>`;}
function pupil(){return `${appHeader('team')}<main id="main" class="phone-shell"><div class="phone-kicker"><span>${icon(state.me.slot)} TEAM ${esc(state.me.name)}</span><span>${state.phase==='lobby'?'Ready, chef':`Q${state.questionNumber}/20`}</span></div><nav class="phone-tabs" aria-label="Team sections">${[['play','Play','🍳'],['pantry','Pantry','🧺'],['recipes','Recipes','📖']].map(([tab,label,emoji])=>btn(`${emoji} ${label}${tab==='pantry'?` <span>${totalStock(state.me.inventory)}</span>`:tab==='recipes'&&state.me.recipes?.length?` <span>${state.me.recipes.length}</span>`:''}`,`tab-${tab}`,`phone-tab ${ui.tab===tab?'active':''}`,`aria-current="${ui.tab===tab?'page':'false'}"`)).join('')}</nav>${ui.tab==='recipes'?recipeBook():ui.tab==='pantry'?pantryView():pupilPlay()}<div class="phone-footer"><span class="room-chip">ROOM <b>${esc(pin)}</b></span><span>Your place is saved on this device.</span></div></main>`;}
function pupilPlay(){switch(state.phase){case'lobby':return `<section class="phone-welcome"><div class="welcome-image"><img src="./assets/kitchen-hero.png" alt="A cheerful chef preparing for service"></div><div class="welcome-copy"><span class="eyebrow">YOU’RE ON THE TEAM</span><h1>Looking sharp,<br><em>chef.</em></h1><p>Your teacher will start the game soon. Talk to your team and get ready.</p><div class="ready-status"><i class="live-dot"></i> Connected & ready</div></div></section><div class="phone-rules"><p><span>✍️</span> Answer together to earn ingredients</p><p><span>🍳</span> Cook with exactly 3 ingredients</p><p><span>★</span> Discover dishes and collect stars</p></div>`;case'question':return pupilQuestion();case'reveal':return `${pupilSubmission()}${questionStage('team')}<div class="phone-wait"><span class="spinner"></span> ${'Cook or save comes next. Waiting for your teacher.'}</div>`;case'rush':return cookingView();case'finished':return `${finalStage('team')}<div class="personal-total"><span>Your team earned</span><strong>${state.me.stars} ★</strong><p>${state.me.recipes?.length || 0} recipes discovered. What a service!</p></div>${leaderboard()}`;default:return'';}}
function pupilSubmission(){const sub=state.me.submission;if(!sub)return'';return `<section class="submission-status ${esc(sub.status)}"><span class="submission-icon">${sub.status==='accepted'?'✓':sub.status==='rejected'?'↻':'✓'}</span><div><h2>${sub.status==='accepted'?'Nicely done, chef!':sub.status==='rejected'?'One to learn from.':'Order received!'}</h2><p>${sub.status==='accepted'?`${INGREDIENTS[sub.reward] || '🥣'} +1 ${esc(sub.reward || 'ingredient')} added to your pantry.`:sub.status==='rejected'?'Your teacher didn’t accept this answer. Watch the reveal and try the next one.':'Your answer is saved. Waiting for your teacher to review it.'}</p></div></section>`;}
function pupilQuestion(){const q=state.question;if(!q)return'';const sub=state.me.submission;return `<section class="phone-question"><div class="question-topline"><span class="eyebrow">${esc(FORMAT[q.format])}</span><span class="question-index">${String(state.questionNumber).padStart(2,'0')}</span></div><p class="question-instruction">${esc(q.instruction)}</p><h1 class="question-prompt">${prompt(q)}</h1>${sub?`${pupilSubmission()}<div class="your-answer"><span class="eyebrow">YOUR TEAM’S ANSWER</span><p>${esc(sub.answer)}</p></div>`:answerInput(q)}<p class="answer-note">Think together. Submit one answer for your team.</p></section>`;}
function answerInput(q){return `<form id="answer-form">${q.format==='typed_correction'?`<label class="input-label" for="team-answer">Replacement for the bold words</label><textarea id="team-answer" name="answer" rows="3" maxlength="500" placeholder="Type the replacement only…" autocorrect="off" spellcheck="false"${disabled(ui.busy)}>${esc(ui.answer)}</textarea>`:q.format==='multiple_choice'?`<div class="answer-options">${(q.options || []).map((o,i)=>`<button type="button" data-action="option" data-option="${esc(o.id)}" class="answer-option ${ui.answer===o.text?'selected':''}" aria-pressed="${ui.answer===o.text}"${disabled(ui.busy)}><span>${String.fromCharCode(65+i)}</span><b>${esc(o.text)}</b><i>${ui.answer===o.text?'✓':''}</i></button>`).join('')}</div>`:`<div class="sentence-builder"><span class="input-label">Tap words to build your sentence</span><div class="built-sentence" aria-label="Your sentence">${ui.wordOrder.length?ui.wordOrder.map((id,i)=>{const t=q.tokens.find(t=>t.id===id);return `<button type="button" class="word-chip selected" data-action="remove-word" data-index="${i}" aria-label="Remove ${esc(t?.text)}">${esc(t?.text)} <span>×</span></button>`;}).join(''):'<span class="sentence-placeholder">Your sentence starts here…</span>'}</div><div class="available-words">${(q.tokens || []).map(t=>`<button type="button" data-action="add-word" data-token="${esc(t.id)}" class="word-chip"${disabled(ui.busy||ui.wordOrder.includes(t.id))}>${esc(t.text)}</button>`).join('')}</div>${btn('Start again','clear-words','text-button')}</div>`}<button type="submit" class="button green wide submit-answer"${disabled(ui.busy || !answerValue(q).trim())}>${ui.busy?'Sending your answer…':'Submit team answer →'}</button></form>`;}
function answerValue(q){return q?.format==='sentence_rebuild'?ui.wordOrder.map(id=>q.tokens.find(t=>t.id===id)?.text || '').join(' '):ui.answer;}
function pantryView(){const inv=state.me.inventory;return `<section class="pantry-heading"><span class="eyebrow">YOUR SECRET INGREDIENTS</span><h1>The pantry.</h1><p>${totalStock(inv)} ingredients. Endless possibilities.</p></section>${ingredientGrid(false)}<div class="pantry-note"><span>💡</span><p>Keep these ingredients until cooking time. Choose any three, including repeats if you have them. The order doesn’t matter.</p></div>${powersView(false)}${state.phase==='rush'?btn('Back to cooking →','tab-play','button green wide'):''}`;}
function ingredientGrid(interactive){return `<div class="ingredient-grid ${interactive?'interactive':''}">${Object.entries(INGREDIENTS).map(([name,emoji])=>{const owned=Number(state.me.inventory?.[name] || 0),selected=ui.selected.filter(x=>x===name).length,available=owned-selected;return interactive?`<article class="ingredient-card ${!owned?'empty':''} ${selected?'chosen':''}"><button type="button" data-action="add-ingredient" data-ingredient="${name}" class="ingredient-add" aria-label="Add ${name}; ${available} available"${disabled(ui.busy||available<1||ui.selected.length>=3||!rushActive())}><span class="ingredient-emoji">${emoji}</span><b>${name}</b><small>${available} available</small><span class="ingredient-plus">+</span></button>${selected?btn('−','remove-ingredient','ingredient-minus',`data-ingredient="${name}" aria-label="Remove one ${name}"${disabled(ui.busy)}`):''}${selected?`<span class="selected-quantity">${selected} in pan</span>`:''}</article>`:`<article class="ingredient-card pantry-item ${!owned?'empty':''}"><span class="ingredient-emoji">${emoji}</span><b>${name}</b><strong>×${owned}</strong></article>`;}).join('')}</div>`;}
function cookingView(){const active=rushActive();return `<div class="phone-rush-heading"><div><span class="eyebrow">${state.questionNumber===20?'THE FINAL SERVICE':`ROUND ${state.questionNumber} · COOK OR SAVE`}</span><h1>${active?state.questionNumber===20?'Last orders!':'Let’s cook.':'Pans down!'}</h1></div><div class="phone-timer ${remaining()<=10?'urgent':''}"><strong data-timer>${remaining()}</strong><span>SECONDS</span></div></div>${!active?`<div class="service-ended"><span>🛎️</span><h2>Service complete.</h2><p>Your ingredients are saved. Wait for your teacher to continue.</p></div>${recentCooks()}${btn('See my pantry','tab-pantry','button secondary wide')}`:`<section class="cooking-station"><div class="pan-heading"><h2>What’s in your pan?</h2><span>${ui.selected.length}/3</span></div><div class="pan-slots">${Array.from({length:3},(_,i)=>`<button type="button" class="pan-slot ${ui.selected[i]?'filled':''}" data-action="remove-slot" data-index="${i}" aria-label="${ui.selected[i]?`Remove ${ui.selected[i]}`:`Empty ingredient slot ${i+1}`}"${disabled(!ui.selected[i]||ui.busy)}><span>${ui.selected[i]?INGREDIENTS[ui.selected[i]]:'+'}</span><small>${esc(ui.selected[i] || 'Ingredient')}</small>${ui.selected[i]?'<i>×</i>':''}</button>`).join('')}</div><button type="button" class="button coral wide cook-button" data-action="cook"${disabled(ui.selected.length!==3||ui.busy)}>${ui.busy&&pending?.type==='pupil:cook'?'<span class="pan-bounce">🍳</span> Cooking…':'🍳 Cook this combination'}</button><p class="tiny muted">Every attempt uses all 3 ingredients. You can save them instead.</p></section><div class="pantry-label"><h2>Pick your ingredients</h2><span>${totalStock(state.me.inventory)} in your pantry</span></div>${ingredientGrid(true)}${totalStock(state.me.inventory)<3?`<p class="empty-pantry">You need at least 3 ingredients to cook. Save your stock for the next rush.</p>`:''}${powersView(true)}`}`;}
function powersView(interactive){const powers=state.me.powers || [];if(!powers.length)return'';return `<section class="powers-card"><div class="powers-heading"><span>🕵️</span><div><span class="eyebrow">A LITTLE KITCHEN MISCHIEF</span><h2>Sneaky Snack <span>×${powers.length}</span></h2></div></div><p>Use one power to take one random ingredient from another team. Their stars stay safe.</p>${interactive?btn('Choose a rival →','choose-rival','button green wide',disabled(ui.busy||!rushActive())):'<small>Ready to use during any cooking phase.</small>'}</section>`;}
function recipeBook(){const recipes=state.me.recipes || [];return `<section class="pantry-heading"><span class="eyebrow">YOUR TEAM’S DISCOVERIES</span><h1>The recipe book.</h1><p>${recipes.length?'A little less mystery. A little more mastery.':'Every great chef starts with a blank page.'}</p></section>${recipes.length?`<div class="recipe-list">${recipes.map(r=>`<article class="recipe-card"><span class="recipe-emoji">${esc(r.emoji || '🍽️')}</span><div><h2>${esc(r.name)}</h2><div class="recipe-ingredients">${(r.ingredients || []).map(i=>`<span>${INGREDIENTS[i] || ''} ${esc(i)}</span>`).join('')}</div><span class="recipe-value">${['power','steal'].includes(r.type)?'🕵️ Makes one stored steal power':`${r.stars} ★ every time you cook it`}</span></div></article>`).join('')}</div>`:`<div class="empty-recipes"><span>📖</span><h2>Something delicious<br>is waiting to be discovered.</h2><p>Try three ingredients during a cooking phase. Successful recipes will appear here, just for your team.</p><div class="mystery-recipe">? <span>+</span> ? <span>+</span> ? <span>=</span> ✦</div></div>`}`;}
function modal(){if(ui.review&&mode==='host')return answerReviewModal();if(!ui.modal)return'';if(ui.modal.type==='confirm-close')return `<div class="modal-backdrop"><section class="modal-card compact-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><span class="big-symbol">🛎️</span><h2 id="modal-title">Close this kitchen?</h2><p>This ends the room for everyone. You can create a fresh kitchen from the home page.</p><div class="modal-actions">${btn('Keep playing','close-modal','button secondary')}${btn('End room','confirm-close','button coral',disabled(ui.busy))}</div></section></div>`;
 if(ui.modal.type==='rival')return `<div class="modal-backdrop"><section class="modal-card rival-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${btn('×','close-modal','modal-close icon-button','aria-label="Close rival selection"')}<span class="big-symbol">🕵️</span><span class="eyebrow">SNEAKY SNACK</span><h2 id="modal-title">Who’s got the goods?</h2><p>Take one random ingredient. Empty pantries are off limits.</p><div class="rival-list">${state.teams.filter(t=>t.id!==state.me.id).map(t=>btn(`<span>${icon(t.slot)}</span><span><b>${esc(t.name)}</b><small>${t.canBeStolenFrom===false&&t.inventoryCount>0?'Already targeted this round':`${t.inventoryCount} ingredients`}</small></span><span>→</span>`,'steal','rival-button',`data-team="${esc(t.id)}"${disabled(ui.busy||!rushActive()||t.inventoryCount<1||t.canBeStolenFrom===false)}`)).join('')}</div><small class="muted">Each team can be targeted only once per rush. If the target is unavailable, your power is kept.</small></section></div>`;
 const c=ui.modal.cook,d=c?.dish || {},success=d.success!==false,power=['power','steal'].includes(d.type)||d.name==='Sneaky Snack';return `<div class="modal-backdrop"><section class="modal-card dish-modal ${success?'':'burnt-modal'}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${btn('×','close-modal','modal-close icon-button','aria-label="Close dish result"')}<span class="eyebrow">${power?'A SECRET’S OUT':!success?'EXPERIMENTAL CUISINE':c.discoveryBonus?'FIRST IN THE WHOLE KITCHEN!':c.isNewForTeam?'NEW RECIPE DISCOVERED':'ORDER UP!'}</span><div class="result-dish">${esc(d.emoji || (success?'🍽️':'💨'))}</div><h2 id="modal-title">${esc(d.name || (success?'A delicious discovery':'Burnt surprise'))}</h2><p>${power?'A Sneaky Snack power is ready! Choose a rival during cooking time and take one random ingredient.':success?'That’s one for the recipe book. Brilliant cooking, chef.':'Well, that was an adventure. Try a different combination next time. Your existing stars are safe.'}</p><div class="result-stars">${Number(c.starsEarned)>0?`+${c.starsEarned} <span>★</span>`:power?'🕵️ +1 power':'0 ★'}</div>${c.discoveryBonus?'<div class="discovery-bonus">✦ Includes +1 first-discovery bonus</div>':''}<div class="dish-ingredients">${(c.ingredients || []).map(i=>`<span>${INGREDIENTS[i] || ''} ${esc(i)}</span>`).join('')}</div>${btn(rushActive()?'Back to the kitchen →':'Lovely. Back to the team.','close-modal','button green wide')}</section></div>`;}
async function api(path,body,auth=token){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const response=await fetch(path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(auth?{Authorization:`Bearer ${auth}`}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal,cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('The kitchen server returned an unexpected response. Please try again.');}if(!response.ok){const error=new Error(data.error || 'That action could not be completed.');error.status=response.status;error.code=data.code;throw error;}return data;}finally{clearTimeout(timeout);}}
function applyState(next,force=false){if(!next||String(next.pin)!==pin)return false;if(state&&String(state.pin)===String(next.pin)&&Number.isFinite(state.version)&&Number.isFinite(next.version)&&next.version<state.version)return false;const oldPhase=state?.phase,oldQuestion=state?.question?.id;state=next;queuePublicCooks(next);if(next.serverTime)clockOffset=Number(next.serverTime)-Date.now();if(oldQuestion!==next.question?.id){ui.answer='';ui.wordOrder=[];ui.questionId=next.question?.id;ui.review=false;}if(oldPhase!==next.phase){ui.selected=[];ui.tab='play';if(ui.modal?.type==='rival')ui.modal=null;if(oldPhase)announce(phaseLabel());}if(state.me){const used={};ui.selected=ui.selected.filter(n=>{used[n]=(used[n]||0)+1;return used[n]<=(state.me.inventory?.[n]||0);});}const signature=JSON.stringify({...next,serverTime:0});if(force||signature!==ui.signature){ui.signature=signature;render();}}
function joinRecoveryView(){return `<div class="site-shell narrow"><header class="site-header">${brand(true)}${connection()}</header><main id="main" class="center-state"><span class="loading-pan" aria-hidden="true">🍳</span><h1>Saving your team’s place…</h1><p>We’re confirming ${esc(pendingJoin.name)} in room ${esc(pendingJoin.pin)}. If your teacher has already started, we’ll reconnect you to the same team.</p><p class="tiny muted">Keep this page open. Your original team choice is saved while we reconnect.</p>${btn('Retry connection','retry-join','button green',disabled(!!joinInFlight&&joinInFlight.generation===routeGeneration))}<a class="text-link" href="./index.html">Back to the kitchen</a></main></div>`;}
async function beginJoin(){
  if(mode!=='join'||token||pendingJoin||ui.loading)return;
  let clientId=storage.get('crazy-kitchen:clientId');if(!clientId){clientId=uid();storage.set('crazy-kitchen:clientId',clientId);}
  pendingJoin={pin,clientId,teamSlot:ui.slot,name:ui.teamName.trim()};
  storage.set(pendingJoinKey(),JSON.stringify(pendingJoin));ui.loading=true;ui.error='';joinRetryDelay=3000;render();
  await deliverPendingJoin();
}
async function deliverPendingJoin(){
  if(mode!=='join'||token||!pendingJoin||(joinInFlight&&joinInFlight.generation===routeGeneration))return;
  const attempt={generation:routeGeneration,pin,join:pendingJoin};joinInFlight=attempt;joinLastAttempt=Date.now();
  try{
    const data=await api(`${API_BASE}/${encodeURIComponent(attempt.pin)}/join`,{clientId:attempt.join.clientId,teamSlot:attempt.join.teamSlot,name:attempt.join.name},'');
    if(attempt.generation!==routeGeneration||pendingJoin!==attempt.join)return;
    if(typeof data.teamToken!=='string'||!data.teamToken)throw new Error('The team confirmation was incomplete. Reconnecting safely.');
    storage.set(`crazy-kitchen:team:${attempt.pin}`,data.teamToken);storage.remove(pendingJoinKey(attempt.pin));
    token=data.teamToken;pendingJoin=null;ui.loading=false;ui.online=true;ui.error='';joinRetryDelay=3000;
    routeGeneration++;state=null;ui.signature='';render();await loadState();
  }catch(error){
    if(attempt.generation!==routeGeneration||pendingJoin!==attempt.join)return;
    if(error.status>=400&&error.status<500&&error.status!==429){
      storage.remove(pendingJoinKey(attempt.pin));pendingJoin=null;ui.loading=false;ui.slot=0;ui.error=error.message;
      await loadState();render();
    }else{ui.online=false;joinRetryDelay=Math.min(30000,joinRetryDelay*1.6);render();}
  }finally{if(joinInFlight===attempt){joinInFlight=null;if(mode==='join'&&pendingJoin)render();}}
}
async function loadState(){
  if(mode==='home'||(pollInFlight&&pollInFlight.generation===routeGeneration))return;
  const request={generation:routeGeneration,pin,mode,token};pollInFlight=request;
  try{
    const data=await api(`${API_BASE}/${encodeURIComponent(request.pin)}/state`,undefined,request.mode==='screen'?'':request.token);
    if(request.generation!==routeGeneration)return;
    const reconnect=!ui.online;ui.online=true;applyState(data.state || data,reconnect);if(reconnect)announce('Reconnected to your kitchen.');
  }catch(error){
    if(request.generation!==routeGeneration)return;
    if(error.status){if(!state){ui.error=error.message;render();}else if(error.status===401){ui.error='Your saved kitchen session could not be verified. Refresh the page to reconnect.';render();}}
    else{if(ui.online){ui.online=false;render();}if(!state&&!pendingJoin){ui.error='We couldn’t reach your kitchen. Check your connection or room PIN.';render();}}
  }finally{if(pollInFlight===request)pollInFlight=null;}
}
async function sendAction(type,extra={}){if(pending||ui.busy)return;pending={type,requestId:uid(),...extra,...(['host:reveal','host:advance','host:end-rush','pupil:cook','pupil:steal'].includes(type)?{questionId:state?.question?.id,expectedPhase:state?.phase}:{})};storage.set(pendingKey(),JSON.stringify(pending));ui.busy=true;ui.error='';render();await deliverPending();}
async function deliverPending(){
  if(!pending||(actionInFlight&&actionInFlight.generation===routeGeneration))return;
  const request={generation:routeGeneration,pin,token,action:pending};actionInFlight=request;lastAttempt=Date.now();
  try{
    const data=await api(`${API_BASE}/${encodeURIComponent(request.pin)}/action`,request.action,request.token);
    if(request.generation!==routeGeneration||request.action!==pending)return;
    const action=request.action;pending=null;ui.busy=false;retryDelay=3000;storage.remove(pendingKey());ui.online=true;applyState(data.state,true);
    if(action.type==='pupil:cook'){ui.selected=[];let cook=data.result?.cook || (data.result?.dish?data.result:null);if(!cook)cook=[...(state.latestCooks || [])].reverse().find(c=>c.teamId===state.me?.id);if(cook)ui.modal={type:'dish',cook};render();}
    if(action.type==='pupil:steal'){ui.modal=null;setNotice(data.result?.ingredient?`${INGREDIENTS[data.result.ingredient] || '🥣'} One ${data.result.ingredient} added to your pantry!`:'Sneaky Snack used. Your pantry is up to date.');render();}
    if(action.type==='host:close')ui.modal=null;render();
  }catch(error){
    if(request.generation!==routeGeneration||request.action!==pending)return;
    if(error.status>=400&&error.status<500&&error.status!==429){pending=null;ui.busy=false;storage.remove(pendingKey());ui.error=error.message;if(request.action.type==='pupil:steal')ui.modal=null;await loadState();render();}
    else{ui.online=false;ui.busy=true;retryDelay=Math.min(30000,retryDelay*1.6);render();}
  }finally{if(actionInFlight===request)actionInFlight=null;}
}
function navigate(nextMode,nextPin){routeGeneration++;syncParentRoute();mode=nextMode;pin=nextPin;token=mode==='screen'?'':storage.get(credentialKey()) || '';state=null;ui.error='';ui.signature='';ui.slot=0;ui.review=false;ui.modal=null;ui.publicCook=null;seenCookIds.clear();cookQueue=[];cookHistoryInitialized=false;if(cookQueueTimer)clearTimeout(cookQueueTimer);pending=null;pendingJoin=null;ui.busy=false;ui.loading=false;joinRetryDelay=3000;try{pending=JSON.parse(storage.get(pendingKey())||'null');ui.busy=!!pending;}catch{}if(mode==='join'){if(token)storage.remove(pendingJoinKey());else{pendingJoin=readPendingJoin(pin);if(pendingJoin){ui.slot=pendingJoin.teamSlot;ui.teamName=pendingJoin.name;ui.loading=true;}}}render();if(pendingJoin)deliverPendingJoin();loadState();if(pending&&token)deliverPending();}
function readRoute(){const params=new URLSearchParams(location.search);const key=['host','screen','join'].find(key=>params.has(key));navigate(key||'home',key?(params.get(key)||'').replace(/[^0-9]/g,''):'');}
async function copy(text,label){try{await navigator.clipboard.writeText(text);setNotice(label);render();}catch{ui.modal=null;ui.error=`Couldn’t copy automatically. ${label.includes('PIN')?'Room PIN: ':''}${text}`;render();}}
app.addEventListener('input',e=>{if(e.target.id==='team-answer'){ui.answer=e.target.value;const b=$('.submit-answer');if(b)b.disabled=ui.busy||!ui.answer.trim();}if(e.target.id==='team-name')ui.teamName=e.target.value;if(e.target.form?.id==='create-form')ui.form[e.target.name]=e.target.value;});
app.addEventListener('change',e=>{if(e.target.form?.id==='create-form')ui.form[e.target.name]=e.target.value;});
app.addEventListener('submit',async e=>{e.preventDefault();const id=e.target.id;if(id==='pin-form'){const code=new FormData(e.target).get('pin').trim();if(!/^\d{5}$/.test(code)){ui.error='Enter the room PIN your teacher shared.';render();return;}history.pushState({},'',`./index.html?join=${code}`);syncParentRoute();navigate('join',code);return;}if(id==='answer-form'){const answer=answerValue(state.question).trim();if(answer)await sendAction('pupil:submit',{questionId:state.question.id,answer});return;}if(id==='team-form'){await beginJoin();return;}if(ui.loading)return;ui.loading=true;ui.error='';render();try{if(id==='create-form'){const data=await api(API_BASE,{teamCount:Number(ui.form.teamCount),rushSeconds:Number(ui.form.rushSeconds),roomName:ui.form.roomName.trim() || 'Crazy Kitchen'},'');storage.set(`crazy-kitchen:host:${data.pin}`,data.hostToken);history.pushState({},'',`./index.html?host=${data.pin}`);syncParentRoute();ui.loading=false;navigate('host',String(data.pin));}}catch(error){ui.error=error.message || 'Please check your connection and try again.';ui.loading=false;render();}});
app.addEventListener('click',async e=>{if(e.target.classList?.contains('review-backdrop')&&!ui.busy){ui.review=false;render();return;}const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;switch(action){case'clear-error':ui.error='';break;case'clear-notice':ui.notice='';break;case'reload':ui.error='';loadState();break;case'retry':deliverPending();return;case'retry-join':deliverPendingJoin();return;case'copy-join':copy(`${state?.joinUrl || shareUrl('join')}`,'Join link copied. Share it with your teams.');return;case'copy-pin':copy(pin,'Room PIN copied.');return;case'fullscreen':try{if(document.fullscreenElement){await document.exitFullscreen();}else{await document.documentElement.requestFullscreen();}}catch{setNotice('Use your browser’s fullscreen control to fill the screen.');}break;case'toggle-review':ui.review=!ui.review;break;case'start':await sendAction('host:start');return;case'reveal':await sendAction('host:reveal');return;case'advance':await sendAction('host:advance');return;case'end-rush':await sendAction('host:end-rush');return;case'accept':case'reject':await sendAction('host:review',{teamId:target.dataset.team,questionId:state.question.id,decision:action==='accept'?'accepted':'rejected'});return;case'end-confirm':ui.modal={type:'confirm-close'};break;case'confirm-close':await sendAction('host:close');return;case'close-modal':ui.modal=null;break;case'select-team':ui.slot=Number(target.dataset.slot);break;case'option':ui.answer=state.question.options.find(o=>String(o.id)===target.dataset.option)?.text || '';break;case'add-word':if(!ui.wordOrder.includes(target.dataset.token))ui.wordOrder.push(target.dataset.token);break;case'remove-word':ui.wordOrder.splice(Number(target.dataset.index),1);break;case'clear-words':ui.wordOrder=[];break;case'add-ingredient':if(rushActive()&&ui.selected.length<3&&ui.selected.filter(n=>n===target.dataset.ingredient).length<(state.me.inventory[target.dataset.ingredient]||0))ui.selected.push(target.dataset.ingredient);break;case'remove-ingredient':{const index=ui.selected.lastIndexOf(target.dataset.ingredient);if(index>=0)ui.selected.splice(index,1);break;}case'remove-slot':ui.selected.splice(Number(target.dataset.index),1);break;case'cook':if(ui.selected.length===3&&rushActive())await sendAction('pupil:cook',{ingredients:[...ui.selected]});return;case'choose-rival':ui.modal={type:'rival'};break;case'steal':{const power=state.me.powers?.find(p=>p.type==='steal');if(power)await sendAction('pupil:steal',{targetTeamId:target.dataset.team,powerId:power.id});return;}default:if(action.startsWith('tab-')){ui.tab=action.slice(4);window.scrollTo({top:0,behavior:'smooth'});}}render();if(ui.modal||ui.review){$('.modal-card button')?.focus({preventScroll:true});}});
document.addEventListener('keydown',e=>{if(!ui.modal&&!ui.review)return;if(e.key==='Escape'&&!ui.busy){ui.modal=null;ui.review=false;render();return;}if(e.key==='Tab'){const buttons=[...document.querySelectorAll('.modal-card button:not(:disabled),.modal-card a[href]')];if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
function updateTimers(){const seconds=remaining();document.querySelectorAll('[data-timer]').forEach(el=>{el.textContent=String(seconds).padStart(2,'0');el.closest('.phone-timer,.rush-clock')?.classList.toggle('urgent',seconds<=10);});if(state?.phase==='rush'&&!state.rushEnded&&seconds===0&&!ui.timerExpired){ui.timerExpired=true;render();loadState();}if(state?.phase!=='rush'||seconds>0)ui.timerExpired=false;}
window.addEventListener('popstate',readRoute);window.addEventListener('online',()=>{ui.online=true;loadState();deliverPending();deliverPendingJoin();});window.addEventListener('offline',()=>{ui.online=false;render();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadState();});
setInterval(()=>{if(mode!=='home'){loadState();if(pending&&token&&Date.now()-lastAttempt>retryDelay)deliverPending();if(pendingJoin&&Date.now()-joinLastAttempt>joinRetryDelay)deliverPendingJoin();}},1000);setInterval(updateTimers,250);
